INSERT INTO naesin_templates (title, template_topic, questions, answer_key, category, mode)
VALUES (
  '최상급 Step3',
  '최상급',
  '[
    {"number":1,"question":"[다음 표의 내용을 보고 빈칸에 들어갈 알맞은 말을 쓰시오]\n\n| Name | Height |\n| Yuna | 148 cm |\n| Minjun | 172 cm |\n| Haeun | 163 cm |\n\nYuna is 148 cm tall and Minjun is 172 cm tall.\nYuna is ______ ______ and Minjun is ______ ______.","answer":"the shortest, the tallest","acceptedAnswers":["the shortest / the tallest","the shortest and the tallest","the shortest,the tallest","the shortest , the tallest"]},
    {"number":2,"question":"[다음 표의 내용을 보고 빈칸에 들어갈 알맞은 말을 쓰시오]\n\n| Name | Age |\n| Yuna | 13 |\n| Minjun | 15 |\n| Haeun | 14 |\n\nYuna is 13 years old and Minjun is 15 years old.\nYuna is ______ ______ and Minjun is ______ ______.","answer":"the youngest, the oldest","acceptedAnswers":["the youngest / the oldest","the youngest and the oldest","the youngest,the oldest","the youngest , the oldest"]},
    {"number":3,"question":"[다음 표를 참고하여 문장을 완성하시오]\n\nSoccer Team Members\n| Name | Age | Height | Weight | 50m Record |\n| Doyun | 15 | 170 | 65 | 8s |\n| Siwoo | 16 | 165 | 58 | 7s |\n| Jiwoo | 14 | 158 | 52 | 9s |\n| Harin | 17 | 175 | 72 | 10s |\n\n나이를 기준으로 볼 때,\nHarin is __________________ student on the team.","answer":"the oldest","acceptedAnswers":["The oldest"]},
    {"number":4,"question":"[다음 표를 참고하여 문장을 완성하시오]\n\nSoccer Team Members\n| Name | Age | Height | Weight | 50m Record |\n| Doyun | 15 | 170 | 65 | 8s |\n| Siwoo | 16 | 165 | 58 | 7s |\n| Jiwoo | 14 | 158 | 52 | 9s |\n| Harin | 17 | 175 | 72 | 10s |\n\n키를 기준으로 볼 때,\nJiwoo is __________________ student on the team.","answer":"the shortest","acceptedAnswers":["The shortest"]},
    {"number":5,"question":"[다음 세 사람에 관한 정보를 보고, 괄호 안의 단어를 활용하여 문장을 완성하시오]\n\n| Jihun | Taeyoung | Seungho |\n| 18 years old | 28 years old | 35 years old |\n| 175cm 68kg | 180cm 78kg | 172cm 65kg |\n\nJihun is __________________ of the three. (young)","answer":"the youngest","acceptedAnswers":["The youngest"]},
    {"number":6,"question":"[다음 건물 정보를 보고 빈칸에 알맞은 말을 쓰시오]\n\n| Lotte Tower | 63 Building |\n| Seoul | Seoul |\n| 555m, 2017 | 249m, 1985 |\n\nLotte Tower is ______ ______ 63 Building.","answer":"taller than","acceptedAnswers":["Taller than"]},
    {"number":7,"question":"[다음 메뉴를 보고 빈칸에 알맞은 말을 쓰시오]\n\n| Food | Price |\n| Bibimbap | $12 |\n| Fried Chicken | $18 |\n| Kimbap | $5 |\n\n(1) Kimbap is __________________ food on the menu.\n(2) Fried chicken is __________________ kimbap.","answer":"the cheapest, more expensive than","acceptedAnswers":["the cheapest / more expensive than","the cheapest and more expensive than","the cheapest,more expensive than","the cheapest , more expensive than"]},
    {"number":8,"question":"[다음 음료 정보를 보고 빈칸에 알맞은 말을 쓰시오]\n\n| Drink | Size | Price |\n| Small Coffee | 250ml | $3 |\n| Medium Coffee | 400ml | $5 |\n| Large Coffee | 600ml | $7 |\n\nThe large coffee is ______ ______ the small coffee.","answer":"bigger than","acceptedAnswers":["Bigger than","larger than","Larger than"]},
    {"number":9,"question":"[다음 표를 보고 괄호 안의 주어진 단어를 이용하여 문장을 완성하시오]\n\n국가 면적 순위\n| 순위 | 국가 | 면적(km²) |\n| 1 | Russia | 17,075,200 |\n| 2 | Canada | 9,984,670 |\n| 3 | USA | 9,826,676 |\n\nⓐ Russia __________________ the three. (big)\nⓑ Canada __________________ the United States. (large)","answer":"is the biggest of, is larger than","acceptedAnswers":["is the biggest of / is larger than","is the biggest of and is larger than","is the biggest of,is larger than","is the biggest of , is larger than"]},
    {"number":10,"question":"[다음 표를 보고 주어진 단어를 활용하여 빈칸을 완성하시오]\n\n| | Jiwoo | Seojun | Hayoon |\n| age | 13 | 13 | 14 |\n| height | 158cm | 162cm | 162cm |\n| weight | 48kg | 65kg | 42kg |\n\n(1) Jiwoo is __________________ Seojun. (old)\n(2) Jiwoo is __________________ Hayoon. (short)\n(3) Hayoon is __________________ of the three. (light)","answer":"as old as, shorter than, the lightest","acceptedAnswers":["as old as / shorter than / the lightest","as old as, shorter than, The lightest","as old as / shorter than / The lightest"]},
    {"number":11,"question":"[다음 표의 각 항목에 대한 과목 순위를 보고 빈칸에 각각 알맞은 말을 쓰시오]\n\n| subject | Korean | math | science | art |\n| easy 순위 | 1 | 4 | 3 | 2 |\n| boring 순위 | 3 | 2 | 1 | 4 |\n\n(1) I think Korean __________________ of all.\n(2) I think art __________________ than science.\n(3) I think math is not as ______ as Korean.","answer":"is the easiest, is easier, easy","acceptedAnswers":["is the easiest / is easier / easy","is the easiest, is easier, Easy","is the easiest / is easier / Easy"]},
    {"number":12,"question":"[다음 표의 내용과 일치하도록 빈칸에 알맞은 말을 차례대로 쓰시오]\n\n| | history books | magazines | comic books |\n| Soyeon | 30 | 55 | 18 |\n| Jihwan | 12 | 20 | 10 |\n| Eunji | 48 | 38 | 48 |\n\nEunji has ______ comic books than Soyeon ______.\nSoyeon has the ______ magazines of three.","answer":"more, does, most","acceptedAnswers":["more / does / most","More, does, most","More / does / most"]},
    {"number":13,"question":"[다음은 나(I)와 친구들에 대한 정보이다. 글의 내용이 표와 일치하도록 빈칸을 완성하시오]\n\n| | I | Yerin | Suho | Jieun |\n| Age | 13 | 13 | 14 | 14 |\n| Height | 155cm | 162cm | 155cm | 168cm |\n| Wake-up | 7:00 | 6:00 | 6:30 | 7:30 |\n\nA: Yerin and I are younger than Suho and Jieun. Suho is ⓐ______ Jieun.\nB: Yerin is taller than I. Suho and I are the same height. Jieun is ⓑ______ of us.\nC: Yerin gets up ⓒ______ Suho.","answer":"as old as, the tallest, earlier than","acceptedAnswers":["as old as / the tallest / earlier than","as old as, The tallest, earlier than","as old as / The tallest / earlier than"]},
    {"number":14,"question":"[다음 표의 내용과 일치하도록 주어진 조건을 포함하여 문장을 완성하시오]\n\n| Phone | Price | Weight | Popularity |\n| X | $90 | 130g | ★★ |\n| Y | $55 | 140g | ★★★★ |\n| Z | $75 | 130g | ★ |\n\n(1) Phone X __________________ in the store. (최상급, 가격)\n(2) Phone Y __________________ in the store. (최상급, 가격)\n(3) Phone Z __________________ Phone Y. (비교급, 무게)","answer":"is the most expensive, is the cheapest, is lighter than","acceptedAnswers":["is the most expensive / is the cheapest / is lighter than","is the most expensive, is the cheapest, Is lighter than","is the most expensive / is the cheapest / Is lighter than"]},
    {"number":15,"question":"[다음 표를 참고하여 2개의 최상급 문장을 <조건>에 맞게 완성하시오]\n\n| | Suho | Jimin | Dain |\n| Age | 13 | 14 | 11 |\n| Height(cm) | 162 | 157 | 135 |\n| Weight(kg) | 58 | 52 | 36 |\n\n<조건> 주어를 서로 다르게 할 것 / 나이, 키, 몸무게 중 2개를 선택할 것\n\n(1) ______________________ among them.\n(2) ______________________ among them.","answer":"Suho is the tallest, Dain is the youngest","acceptedAnswers":["Suho is the tallest / Dain is the youngest","Suho is the tallest and Dain is the youngest","Dain is the youngest, Suho is the tallest","Dain is the youngest / Suho is the tallest","Suho is the tallest, Dain is the lightest","Suho is the tallest / Dain is the lightest","Dain is the lightest, Suho is the tallest","Dain is the lightest / Suho is the tallest","Suho is the heaviest, Dain is the youngest","Suho is the heaviest / Dain is the youngest","Dain is the youngest, Suho is the heaviest","Dain is the youngest / Suho is the heaviest","Suho is the heaviest, Dain is the lightest","Suho is the heaviest / Dain is the lightest","Dain is the lightest, Suho is the heaviest","Dain is the lightest / Suho is the heaviest","Suho is the tallest, Jimin is the oldest","Suho is the tallest / Jimin is the oldest","Jimin is the oldest, Suho is the tallest","Jimin is the oldest / Suho is the tallest","Jimin is the oldest, Dain is the youngest","Jimin is the oldest / Dain is the youngest","Dain is the youngest, Jimin is the oldest","Dain is the youngest / Jimin is the oldest","Jimin is the oldest, Dain is the lightest","Jimin is the oldest / Dain is the lightest","Dain is the lightest, Jimin is the oldest","Dain is the lightest / Jimin is the oldest","Suho is the heaviest, Jimin is the oldest","Suho is the heaviest / Jimin is the oldest","Jimin is the oldest, Suho is the heaviest","Jimin is the oldest / Suho is the heaviest"]},

    {"number":16,"question":"[다음 두 문장의 의미가 서로 통하도록 빈칸을 완성하시오]\n\nThis juice is not as cold as that one.\n= That juice is ______ ______ this juice.","answer":"colder than","acceptedAnswers":["Colder than"]},
    {"number":17,"question":"[다음 두 문장의 의미가 서로 통하도록 빈칸을 완성하시오]\n\nThe jacket is cheaper than the coat.\n= The coat is ______ ______ ______ the jacket.","answer":"more expensive than","acceptedAnswers":["More expensive than"]},
    {"number":18,"question":"[다음 두 문장의 의미가 서로 통하도록 빈칸을 완성하시오]\n\nYour painting is more famous than all the others.\n= Your painting is ______ ______ ______.","answer":"the most famous","acceptedAnswers":["The most famous"]},
    {"number":19,"question":"[다음 두 문장의 의미가 서로 통하도록 빈칸을 완성하시오]\n\nThe rabbit runs faster than the turtle.\n= The turtle runs s______ than the rabbit.","answer":"slower","acceptedAnswers":["Slower"]},
    {"number":20,"question":"[다음 <예시>와 같이 같은 의미를 지닌 문장이 되도록 괄호 안의 단어를 사용하여 쓰시오]\n\n<예시> This bus is more convenient than all the others. (most)\n→ This bus is the most convenient.\n\nThe bedroom isn''t as big as the kitchen. (bigger)\n→ The kitchen is ______ than the bedroom.","answer":"bigger","acceptedAnswers":["Bigger"]},
    {"number":21,"question":"[다음 <예시>와 같이 같은 의미를 지닌 문장이 되도록 괄호 안의 단어를 사용하여 쓰시오]\n\n<예시> This bus is more convenient than all the others. (most)\n→ This bus is the most convenient.\n\nI''m not as fit as you. (are)\n→ You ______ fitter than me.","answer":"are","acceptedAnswers":["Are"]},
    {"number":22,"question":"[다음 <예시>와 같이 같은 의미를 지닌 문장이 되도록 괄호 안의 단어를 사용하여 쓰시오]\n\n<예시> This bus is more convenient than all the others. (most)\n→ This bus is the most convenient.\n\nThe sofa and the chair are the same size. (big)\n→ The sofa is ______ ______ ______ the chair.","answer":"as big as","acceptedAnswers":["As big as"]},
    {"number":23,"question":"[다음 문장과 같은 뜻이 되도록 최상급을 사용하여 문장을 완성하시오]\n\nNo other class in middle school is so easy as English class.\n→ English class is ______________________ in middle school.","answer":"the easiest class","acceptedAnswers":["The easiest class"]},
    {"number":24,"question":"[다음 글을 읽고 빈칸에 알맞은 말을 쓰시오]\n\nAnn''s score is high.\nLisa''s score is higher than Ann''s score.\nMira''s score is higher than Lisa''s score.\n\n→ Mira''s score is ______________________ of the three.","answer":"the highest","acceptedAnswers":["The highest"]},
    {"number":25,"question":"[다음 글을 읽고 빈칸에 알맞은 말을 쓰시오]\n\nI am 150 cm tall.\nKate is 160 cm tall.\nJames is 155 cm tall.\n\n→ I am ______________________ of us.","answer":"the shortest","acceptedAnswers":["The shortest"]},

    {"number":26,"question":"[다음 우리말과 같은 의미가 되도록 괄호에 주어진 단어를 이용하여 빈칸에 알맞은 말을 쓰시오]\n\n그것은 그 시험에서 가장 어려운 문제이다.\n= It ______ ______ ______ ______ problem on the test. (difficult)","answer":"is the most difficult","acceptedAnswers":["Is the most difficult","was the most difficult","Was the most difficult","is the most difficult problem on the test"]},
    {"number":27,"question":"[다음 우리말과 같은 의미가 되도록 괄호에 주어진 단어를 이용하여 빈칸에 알맞은 말을 쓰시오]\n\n지원이는 그가 세상에서 가장 친절한 소년이라고 생각했다!\n= Jiwon thought he was ______ ______ ______ in the world! (kind)","answer":"the kindest boy","acceptedAnswers":["The kindest boy"]},
    {"number":28,"question":"[다음 우리말과 같도록 빈칸에 알맞은 말을 쓰시오]\n\n민수는 우리 반에서 가장 재미있는 사람이다.\n→ Minsu ______ ______ ______ ______ in our class.","answer":"is the funniest person","acceptedAnswers":["Is the funniest person"]},
    {"number":29,"question":"[다음 괄호 안에 주어진 단어를 이용하여 우리말을 영어로 쓰시오]\n\n건강은 인생에서 가장 중요한 것이다.\n(health / in life / important thing)","answer":"Health is the most important thing in life.","acceptedAnswers":["Health is the most important thing in life"]},
    {"number":30,"question":"[다음 우리말에 맞게 괄호 안의 단어를 이용하여 빈칸을 완성하시오]\n\n오늘은 이번 여름 중에서 가장 뜨겁다. (hot)\n→ Today is ______________________ of this summer.","answer":"the hottest day","acceptedAnswers":["The hottest day"]},
    {"number":31,"question":"[다음 우리말에 맞게 괄호 안의 단어를 이용하여 빈칸을 완성하시오]\n\n영어는 나에게 가장 쉽다. (easy)\n→ English is ______________________ to me.","answer":"the easiest subject","acceptedAnswers":["The easiest subject","the easiest","The easiest"]},
    {"number":32,"question":"[다음 우리말을 주어진 단어를 이용하여 영작하시오]\n\nTom은 나만큼 말랐다. (as, thin)","answer":"Tom is as thin as me.","acceptedAnswers":["Tom is as thin as me","Tom is as thin as I am.","Tom is as thin as I am"]},
    {"number":33,"question":"[다음 우리말을 주어진 단어를 이용하여 영작하시오]\n\n 엄마는 우리 가족 중 몸무게가 가장 적게 나간다. (light, in)","answer":"Mom is the lightest in our family.","acceptedAnswers":["Mom is the lightest in our family","My mom is the lightest in our family.","My mom is the lightest in our family"]},
    {"number":34,"question":"[다음 우리말의 의미와 같도록 빈칸에 알맞은 말을 쓰시오]\n\n누가 우리 반에서 가장 키가 큰 학생이니?\n= ______ ______ ______ ______ ______ ______ in our class?","answer":"Who is the tallest student","acceptedAnswers":["who is the tallest student"]},
    {"number":35,"question":"[다음 우리말의 의미가 되도록 빈칸에 알맞은 말을 쓰시오 (단, 괄호 안의 단어를 이용할 것)]\n\nMike는 그의 반에서 가장 많은 책을 가지고 있다.\n→ Mike ____________________________________. (books, class)","answer":"has the most books in his class","acceptedAnswers":["Has the most books in his class"]},
    {"number":36,"question":"[다음 우리말을 영어로 옮기시오]\n\n저 토마토들은 이 가게에서 가장 맛있는 과일이다.","answer":"Those tomatoes are the most delicious fruit in this store.","acceptedAnswers":["Those tomatoes are the most delicious fruit in this store","Those tomatoes are the most delicious fruits in this store.","Those tomatoes are the most delicious fruits in this store"]},
    {"number":37,"question":"[다음 우리말을 영어로 옮기시오]\n\nTom은 그 5명 소년들 중에서 가장 키가 크다.","answer":"Tom is the tallest of the five boys.","acceptedAnswers":["Tom is the tallest of the five boys","Tom is the tallest among the five boys.","Tom is the tallest among the five boys"]},
    {"number":38,"question":"[다음 우리말의 의미가 되도록 주어진 단어를 이용하여 문장을 쓰시오]\n\nShrek은 Toy Story보다 더 재미있다. (funny)","answer":"Shrek is funnier than Toy Story.","acceptedAnswers":["Shrek is funnier than Toy Story"]},
    {"number":39,"question":"[다음 우리말의 의미가 되도록 주어진 단어를 이용하여 문장을 쓰시오]\n\n나의 고양이는 너의 강아지보다 더 크다. (big)","answer":"My cat is bigger than your dog.","acceptedAnswers":["My cat is bigger than your dog"]},
    {"number":40,"question":"[다음 우리말의 의미가 되도록 주어진 단어를 이용하여 문장을 쓰시오]\n\nJongsuk은 우리 반에서 가장 인기 있는 소년이다. (popular, class)","answer":"Jongsuk is the most popular boy in our class.","acceptedAnswers":["Jongsuk is the most popular boy in our class","Jongsuk is the most popular boy in class.","Jongsuk is the most popular boy in class"]},

    {"number":41,"question":"[다음은 기네스북에 기재된 세계 기록에 대한 표이다. <보기>를 참고하여 최상급을 사용하여 문장을 완성하시오]\n\n| How | Name |\n| tall | Mr. Kosen (251cm) |\n| (1) heavy | Mr. Uribe (560kg) |\n| (2) long | the Amazon River (7,062km) |\n\n<보기> The tallest man in the world is Mr. Kosen.\n\n(1) ______________________________________\n(2) ______________________________________","answer":"The heaviest man in the world is Mr. Uribe., The longest river in the world is the Amazon River.","acceptedAnswers":["The heaviest man in the world is Mr. Uribe. The longest river in the world is the Amazon River.","The heaviest man in the world is Mr. Uribe / The longest river in the world is the Amazon River","The heaviest man in the world is Mr. Uribe, The longest river in the world is the Amazon River"]},
    {"number":42,"question":"[다음 대화의 밑줄 친 우리말을 <조건>에 맞게 영어로 쓰시오]\n\nA: Can you help me?\nB: Sure. What is it?\nA: 나는 이 학교에서 가장 똑똑한 학생을 찾으러 왔어.\nB: I think I''m the one you''re looking for.\n\n<조건> come, find, smart를 활용할 것 / 문장의 시제에 맞게 동사를 변형할 것","answer":"I came to find the smartest student in this school.","acceptedAnswers":["I came to find the smartest student in this school"]},
    {"number":43,"question":"[다음 표를 보고 주어진 질문에 영어로 답하시오 (주어와 동사가 있는 완전한 문장으로 쓸 것)]\n\n| Name | Height | Weight |\n| Juhui | 169cm | 47kg |\n| Mina | 164cm | 58kg |\n| Suji | 157cm | 49kg |\n\n(1) 가장 키가 큰 사람은?\n(2) 가장 무거운 사람은?","answer":"Juhui is the tallest., Mina is the heaviest.","acceptedAnswers":["Juhui is the tallest. Mina is the heaviest.","Juhui is the tallest / Mina is the heaviest","Juhui is the tallest, Mina is the heaviest"]},
    {"number":44,"question":"[다음 카메라 정보를 보고 빈칸 ⓐ, ⓑ에 적절한 표현을 영어로 쓰시오]\n\n| Camera | Price | Weight | Zoom |\n| BasicCam | $50 | 200g | 10x |\n| ProCam | $80 | 300g | 15x |\n| EliteCam | $100 | 600g | 30x |\n\nBasicCam is ⓐ__________________ of the three cameras. EliteCam can zoom the best. But it is ⓑ__________________ camera of the three.","answer":"the cheapest, the most expensive","acceptedAnswers":["the cheapest / the most expensive","the cheapest and the most expensive","the cheapest,the most expensive","the cheapest , the most expensive"]},
    {"number":45,"question":"[다음 표를 보고 주어진 질문에 완전한 영어문장으로 답하시오]\n\nWorld Weather Forecast\n| City | Temperature |\n| London | 5°C / 12°C |\n| Dubai | 20°C / 35°C |\n| Oslo | -10°C / -2°C |\n\n<조건> 최상급을 사용할 것 / city와 in the world를 이용할 것\n\n(A) 가장 더운 도시는 어디입니까?\n(B) 가장 추운 도시는 어디입니까?","answer":"Dubai is the hottest city in the world., Oslo is the coldest city in the world.","acceptedAnswers":["Dubai is the hottest city in the world. Oslo is the coldest city in the world.","Dubai is the hottest city in the world / Oslo is the coldest city in the world","Dubai is the hottest city in the world, Oslo is the coldest city in the world"]},
